tion: "Innovations, internet history, AI, software, and tech gadgets.", color: "#3b82f6" }, { id: "computers", name: "Computers", slug: "computers", icon: "🖥️", description: "Computer hardware, operating systems, networking, and architecture.", color: "#6366f1" }, { id: "automotive", name: "Automotive", slug: "automotive", icon: "🚗", description: "Engine mechanics, vehicle diagnostics, automotive systems, and EV tech.", color: "#dc2626" }, { id: "iq-logic", name: "IQ & Logic", slug: "iq-logic", icon: "🧩", description: "Pattern recognition, logic puzzles, deductive reasoning, and brain teasers.", color: "#8b5cf6" }, { id: "mathematics", name: "Mathematics", slug: "mathematics", icon: "📐", description: "Algebra, geometry, arithmetic, probabilities, and calculus fundamentals.", color: "#10b981" }, { id: "english", name: "English & Grammar", slug: "english", icon: "✍️", description: "Grammar rules, vocabulary, idioms, reading comprehension, and syntax.", color: "#f97316" }, { id: "mixed-quiz", name: "Mixed Quiz", slug: "mixed-quiz", icon: "🎲", description: "A dynamic randomized blend of questions across all knowledge categories.", color: "#6b7280" } ] };
